#Requires -Version 5.1

[CmdletBinding()]

param([switch]$Demo, [switch]$ScanOnly)

$script:GoatRoot = $PSScriptRoot

$script:GoatLaunchPath = $PSCommandPath

$script:GoatCoreSource = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))

$script:GoatScannerSource = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))

$script:GoatAdvancedScannerSource = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))

$script:GoatRecommendationSource = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))

$script:GoatRecommendationJson = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))

$script:GoatSelectionSource = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))

$script:GoatToolAdvisorSource = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))

$script:GoatNativeOptionsJson = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))

$script:GoatToolRulesJson = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))

$script:GoatIntegrationSource = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))

$script:GoatUiSource = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))

$script:GoatXaml = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))

$goatCatalogStream = [IO.MemoryStream]::new([Convert]::FromBase64String(''))

$goatCatalogReader = [IO.StreamReader]::new([IO.Compression.GZipStream]::new($goatCatalogStream,[IO.Compression.CompressionMode]::Decompress),[Text.Encoding]::UTF8)

try { $script:GoatCatalogJson = $goatCatalogReader.ReadToEnd() } finally { $goatCatalogReader.Dispose(); $goatCatalogStream.Dispose() }

$script:GoatLogoBase64 = ''

. ([scriptblock]::Create([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))))